import { writeFileSync } from 'node:fs';
const ch = (c) => String.fromCodePoint(c);
// separators to test between GO and the digit
const seps = [0x20, 0x09, 0x0a, 0x0d, 0x0c, 0x0b, 0x1c, 0x1d, 0x1e, 0x1f, 0x85, 0xa0, 0x1680, 0x2000, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0x200b];
const cases = [
  "SELECT 1 GO\n.x",
  "SELECT 1 GO\t.x",
  "SELECT 1 GO  .x",
  "SELECT 1 GO 2.x",
  "SELECT 1 GO 2(3)",
  "SELECT 1 GO 2 .x",
  "GO 0 SELECT 1",
  "GO 007 SELECT 1",
  "GO 999999999999999999999 SELECT 1",
  "GO 2 SELECT 3",
  "GO\r\n2 SELECT 3",
  "GO 2" + ch(0x0662) + " SELECT 3",
  "GO " + ch(0x0662) + " SELECT 3",
  "GO " + ch(0xff12) + " SELECT 3",
  "go 2 SELECT 3",
  "Go 2 SELECT 3",
  "gO 2 SELECT 3",
  "GO 2",
  "GO 2;",
  "GO 2)",
  "GO 2\n",
  "GO 2 "
];
for (const s of seps) {
  cases.push("GO" + ch(s) + "2 SELECT 3");
  cases.push("GO" + ch(s) + "SELECT 3");
}
writeFileSync('/workspace/corpus/tmp-go-a.json', JSON.stringify(cases, null, 1));
console.log(cases.length);

