import { readFileSync } from 'node:fs';
const cps = JSON.parse(readFileSync('/tmp/ws-cps.json', 'utf8'));
const lines = readFileSync('/tmp/ws-out.txt', 'utf8').split('\n');
const outs = lines.filter((l) => l.startsWith('OUT  : ')).map((l) => JSON.parse(l.slice(7)));
console.log('n outs', outs.length, 'n cps', cps.length);
const accepted = [], other = [];
cps.forEach((c, i) => {
  const o = (outs[i] || '').trim();
  if (o.endsWith("2', 'B']")) accepted.push(c); else other.push([c, o]);
});
console.log('ACCEPTED as count separator:', accepted.map((c) => '0x' + c.toString(16)).join(' '));
console.log('');
for (const [c, o] of other) console.log('0x' + c.toString(16).padStart(4, '0'), o);

import { writeFileSync, readFileSync } from 'node:fs';
const ch = (c) => String.fromCodePoint(c);
const out = JSON.parse(readFileSync('/workspace/corpus/probe-go-splitter.json', 'utf8'));
const seen = new Set(out.map((s) => JSON.stringify(s)));
const push = (s) => {
  const k = JSON.stringify(s);
  if (!seen.has(k)) { seen.add(k); out.push(s); }
};
// whitespace-separator sweep (NUL cannot be passed through argv)
for (const s of JSON.parse(readFileSync('/workspace/corpus/tmp-ws.json', 'utf8'))) push(s);
// digit-class sweep: Nd from several blocks + non-Nd numerics
const digits = [0x30, 0x39, 0x660, 0x6f1, 0x966, 0x9e7, 0xa66, 0xbe7, 0xe51, 0x17e2, 0x1c42,
  0xff10, 0xff19, 0x104a1, 0x1d7ce, 0x1d7d0, 0x1e959];
const nonDigits = [0xbd, 0xb2, 0xb3, 0x2070, 0x2075, 0x2160, 0x2189, 0x3007, 0x2153, 0x4e00];
for (const c of digits) push('A GO ' + ch(c) + ' B');
for (const c of nonDigits) push('A GO ' + ch(c) + ' B');
writeFileSync('/workspace/corpus/probe-go-splitter.json', JSON.stringify(out, null, 1) + '\n');
